    }, confirmButton = { TextButton(onClick = { expanded = false }) { Text("완료") } })
}

package com.seolhwa.armyrist.handicap

import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
import org.json.JSONArray
import org.json.JSONObject

enum class HandicapKind { BLACK, WHITE }
enum class WordCategory(val title: String) { WHO("누가"), WHEN("언제"), WHERE("어디서"), WHAT("무엇을"), HOW("어떻게") }
data class SituationWord(val id: String, val text: String)
data class UnitContact(val name: String = "", val phone: String = "") {
    fun normalized() = copy(name = name.trim().take(60), phone = phone.trim().take(40))
}
data class HandicapConfig(
    val issuer: UnitContact = UnitContact(),
    val upper: List<UnitContact> = List(4) { UnitContact() },
    val lower: List<UnitContact> = List(4) { UnitContact() },
    val words: Map<WordCategory, List<SituationWord>> = defaultWords()
) {
    fun normalized() = copy(
        issuer = issuer.normalized(),
        upper = List(4) { upper.getOrNull(it)?.normalized() ?: UnitContact() },
        lower = List(4) { lower.getOrNull(it)?.normalized() ?: UnitContact() },
        words = WordCategory.entries.associateWith { category ->
            words[category].orEmpty().map { it.copy(id = it.id.take(80), text = it.text.trim().take(80)) }
                .filter { it.id.isNotBlank() && it.text.isNotBlank() }.distinctBy { it.id }.take(100)
        }
    )
    companion object {
        fun defaultWords(): Map<WordCategory, List<SituationWord>> = mapOf(
            WordCategory.WHO to listOf("불침번", "위병조장", "위병근무자", "병사(용사)", "영내간부"),
            WordCategory.WHEN to emptyList(),
            WordCategory.WHERE to listOf("위병소", "통합막사", "병영식당", "체력단련장", "생활관", "보일러실"),
            WordCategory.WHAT to listOf("화재", "응급환자", "외부인 침입", "인원 미복귀", "시설 파손"),
            WordCategory.HOW to listOf("발견", "조치", "보고")
        ).mapValues { (category, values) -> values.mapIndexed { index, text -> SituationWord("${category.name}_$index", text) } }
    }
}
data class SituationDraft(
    val kind: HandicapKind? = null,
    val issuer: UnitContact = UnitContact(),
    val who: List<String> = emptyList(),
    val whenText: String = "",
    val where: List<String> = emptyList(),
    val what: List<String> = emptyList(),
    val how: List<String> = emptyList()
)
data class SituationResult(val sentence: String, val recipient: UnitContact, val route: String, val missing: List<String>)
object HandicapRules {
    fun currentTime(now: LocalDateTime) = now.format(DateTimeFormatter.ofPattern("yyyy.MM.dd HH:mm"))
    fun build(config: HandicapConfig, draft: SituationDraft): SituationResult {
        val issuer = draft.issuer.normalized().takeIf { it.name.isNotBlank() } ?: config.issuer.normalized()
        val target = when (draft.kind) {
            HandicapKind.BLACK -> config.upper.getOrNull(0)?.normalized()
            HandicapKind.WHITE -> config.lower.getOrNull(0)?.normalized()
            null -> null
        }
        val hasTarget = target != null && target.name.isNotBlank()
        val recipient = if (hasTarget) target!! else issuer
        val missing = buildList {
            if (draft.kind == null) add("핸디캡 블랙/화이트")
            if (issuer.name.isBlank()) add("상황부여 제대")
            if (draft.who.isEmpty()) add("누가")
            if (draft.whenText.isBlank()) add("언제")
            if (draft.where.isEmpty()) add("어디서")
            if (draft.what.isEmpty()) add("무엇을")
            if (draft.how.isEmpty()) add("어떻게")
        }
        val route = when {
            draft.kind == null -> "핸디캡을 선택해주세요"
            hasTarget && draft.kind == HandicapKind.BLACK -> "블랙 ↑ 1차 상급제대"
            hasTarget -> "화이트 ↓ 1차 하급제대"
            draft.kind == HandicapKind.BLACK -> "1차 상급 미등록 → 상황부여 제대"
            else -> "1차 하급 미등록 → 상황부여 제대"
        }
        fun ordered(category: WordCategory, values: List<String>): String {
            val vocabulary = config.words[category].orEmpty().map { it.text }
            return values.distinct().sortedWith(compareBy<String> { vocabulary.indexOf(it).let { index -> if (index < 0) Int.MAX_VALUE else index } }.thenBy { it }).joinToString(" · ")
        }
        val sentence = "${draft.whenText.ifBlank { "[언제 미입력]" }}, " +
            "${ordered(WordCategory.WHERE, draft.where).ifBlank { "[어디서 미입력]" }}에서 " +
            "${ordered(WordCategory.WHO, draft.who).ifBlank { "[누가 미입력]" }} 관련 " +
            "${ordered(WordCategory.WHAT, draft.what).ifBlank { "[무엇을 미입력]" }} 상황발생.\n수행사항: ${ordered(WordCategory.HOW, draft.how).ifBlank { "[어떻게 미입력]" }}."
        return SituationResult(sentence, recipient, route, missing)
    }
}
object HandicapCodec {
    private fun unit(value: UnitContact) = JSONObject().put("name", value.name).put("phone", value.phone)
    private fun readUnit(j: JSONObject?) = UnitContact(j?.optString("name").orEmpty(), j?.optString("phone").orEmpty())
    private fun strings(values: List<String>) = JSONArray().also { a -> values.forEach { a.put(it) } }
    private fun readStrings(a: JSONArray?) = (0 until (a?.length() ?: 0)).map { a!!.optString(it) }.filter { it.isNotBlank() }.take(100)
    fun encode(config: HandicapConfig, normalize: Boolean = true): String {
        val c = if (normalize) config.normalized() else config
        val words = JSONObject()
        WordCategory.entries.forEach { category -> words.put(category.name, JSONArray().also { a ->
            c.words[category].orEmpty().forEach { a.put(JSONObject().put("id", it.id).put("text", it.text)) }
        }) }
        return JSONObject().put("schemaVersion", 2).put("issuer", unit(c.issuer))
            .put("upper", JSONArray().also { a -> c.upper.forEach { a.put(unit(it)) } })
            .put("lower", JSONArray().also { a -> c.lower.forEach { a.put(unit(it)) } })
            .put("words", words).toString()
    }
    fun decode(raw: String?, normalize: Boolean = true): HandicapConfig = runCatching {
        if (raw.isNullOrBlank()) return HandicapConfig()
        val j = JSONObject(raw)
        val defaults = HandicapConfig()
        HandicapConfig(readUnit(j.optJSONObject("issuer")),
            List(4) { readUnit(j.optJSONArray("upper")?.optJSONObject(it)) },
            List(4) { readUnit(j.optJSONArray("lower")?.optJSONObject(it)) },
            WordCategory.entries.associateWith { category ->
                val a = j.optJSONObject("words")?.optJSONArray(category.name)
                val values = if (a == null) defaults.words[category].orEmpty() else (0 until a.length()).mapNotNull { index ->
                    a.optJSONObject(index)?.let { SituationWord(it.optString("id"), it.optString("text")) }
                }
                if (j.optInt("schemaVersion", 1) < 2 && category == WordCategory.WHERE && a != null) {
                    val migrated = values.map { if (it.id == "WHERE_1" && it.text == "막사") it.copy(text = "통합막사") else it }
                    val additions = defaults.words[category].orEmpty().filter { it.id in listOf("WHERE_4", "WHERE_5") && migrated.none { old -> old.id == it.id || old.text == it.text } }
                    migrated + additions
                } else values
            }).let { if (normalize) it.normalized() else it }
    }.getOrDefault(HandicapConfig())
    fun encodeDraft(d: SituationDraft): String = JSONObject().put("kind", d.kind?.name ?: "")
        .put("issuer", unit(d.issuer)).put("who", strings(d.who)).put("when", d.whenText)
        .put("where", strings(d.where)).put("what", strings(d.what)).put("how", strings(d.how)).toString()
    fun decodeDraft(raw: String?): SituationDraft = runCatching {
        if (raw.isNullOrBlank()) return SituationDraft()
        val j = JSONObject(raw)
        SituationDraft(HandicapKind.entries.firstOrNull { it.name == j.optString("kind") }, readUnit(j.optJSONObject("issuer")),
            readStrings(j.optJSONArray("who")), j.optString("when").take(120), readStrings(j.optJSONArray("where")), readStrings(j.optJSONArray("what")), readStrings(j.optJSONArray("how")))
    }.getOrDefault(SituationDraft())
}

package com.seolhwa.armyrist.home

import android.widget.Toast
import androidx.compose.foundation.gestures.detectDragGesturesAfterLongPress
import androidx.compose.foundation.gestures.scrollBy
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyListState
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.alpha
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.geometry.Rect
import androidx.compose.ui.hapticfeedback.HapticFeedbackType
import androidx.compose.ui.input.pointer.pointerInput
import androidx.compose.ui.layout.LayoutCoordinates
import androidx.compose.ui.layout.onGloballyPositioned
import androidx.compose.ui.layout.positionInRoot
import androidx.compose.ui.platform.LocalContext
import androidx.compose.ui.platform.LocalHapticFeedback
import androidx.compose.ui.semantics.clearAndSetSemantics
import androidx.compose.ui.unit.IntOffset
import androidx.compose.ui.unit.IntSize
import androidx.compose.ui.unit.dp
import androidx.compose.ui.zIndex
import kotlin.math.roundToInt

@Composable
fun HomeToolGrid(listState: LazyListState, viewport: Rect, card: @Composable (id: String, modifier: Modifier, dragging: Boolean) -> Unit) {
    val context = LocalContext.current
    val preferences = remember { context.getSharedPreferences("killomris_home_tools_v1", 0) }
    var order by remember { mutableStateOf(HomeToolOrder.decode(preferences.getString("order", null))) }
    var before by remember { mutableStateOf(order) }
    var dragged by remember { mutableStateOf<String?>(null) }
    var grabOffset by remember { mutableStateOf(Offset.Zero) }
    var pointerRoot by remember { mutableStateOf(Offset.Zero) }
    var gridOrigin by remember { mutableStateOf(Offset.Zero) }
    var coordinates by remember { mutableStateOf<LayoutCoordinates?>(null) }
    var draggedSize by remember { mutableStateOf(IntSize.Zero) }
    // Physical slots remain fixed while tool identities move between them.
    val slots = remember { mutableStateMapOf<Int, Rect>() }
    val haptic = LocalHapticFeedback.current
    val density = androidx.compose.ui.platform.LocalDensity.current
    val inset = with(density) { 12.dp.toPx() }
    val edge = with(density) { 48.dp.toPx() }
    val currentViewport by rememberUpdatedState(viewport)
    fun placeAtPointer() {
        val id = dragged ?: return
        val point = pointerRoot - gridOrigin
        val index = slots.entries.firstOrNull { (_, rect) ->
            Rect(rect.left + inset, rect.top + inset, rect.right - inset, rect.bottom - inset).contains(point)
        }?.key ?: return
        order = HomeToolOrder.moveToIndex(order, id, index)
    }
    LaunchedEffect(dragged) {
        while (dragged != null) {
            withFrameNanos { }
            val bounds = currentViewport
            val speed = when {
                bounds.height <= 0f -> 0f
                pointerRoot.y < bounds.top + edge -> -8f * ((bounds.top + edge - pointerRoot.y) / edge).coerceIn(0f, 1f)
                pointerRoot.y > bounds.bottom - edge -> 8f * ((pointerRoot.y - bounds.bottom + edge) / edge).coerceIn(0f, 1f)
                else -> 0f
            }
            if (speed != 0f) listState.scrollBy(speed)
            placeAtPointer()
        }
    }
    Box(Modifier.fillMaxWidth().onGloballyPositioned { coordinates = it; gridOrigin = it.positionInRoot() }.pointerInput(Unit) {
        detectDragGesturesAfterLongPress(
            onDragStart = { point ->
                val hit = slots.entries.firstOrNull { it.value.contains(point) }
                if (hit != null) {
                    before = order; dragged = order.getOrNull(hit.key)
                    grabOffset = point - hit.value.topLeft; pointerRoot = point + gridOrigin
                    draggedSize = IntSize(hit.value.width.roundToInt(), hit.value.height.roundToInt())
                    haptic.performHapticFeedback(HapticFeedbackType.LongPress)
                }
            },
            onDrag = { change, amount ->
                if (dragged != null) { change.consume(); pointerRoot += amount; placeAtPointer() }
            },
            onDragEnd = {
                placeAtPointer()
                if (dragged != null && order != before) {
                    if (!preferences.edit().putString("order", HomeToolOrder.encode(order)).commit()) {
                        order = before
                        Toast.makeText(context, "배치를 저장하지 못했습니다.", Toast.LENGTH_LONG).show()
                    }
                }
                dragged = null
            },
            onDragCancel = { if (dragged != null) order = before; dragged = null }
        )
    }) {
        Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
            order.chunked(2).forEachIndexed { rowIndex, row ->
                Row(horizontalArrangement = Arrangement.spacedBy(12.dp), modifier = Modifier.fillMaxWidth()) {
                    row.forEachIndexed { columnIndex, id -> key(id) {
                        val index = rowIndex * 2 + columnIndex
                        Box(Modifier.weight(1f).onGloballyPositioned { child ->
                            val parent = coordinates
                            if (parent != null && parent.isAttached && child.isAttached) {
                                val start = parent.localPositionOf(child, Offset.Zero)
                                val rect = Rect(start, androidx.compose.ui.geometry.Size(child.size.width.toFloat(), child.size.height.toFloat()))
                                if (slots[index] != rect) slots[index] = rect
                            }
                        }.alpha(if (id == dragged) 0f else 1f).then(if (id == dragged) Modifier.clearAndSetSemantics { } else Modifier)) {
                            card(id, Modifier.fillMaxWidth(), dragged != null)
                        }
                    } }
                    if (row.size == 1) Spacer(Modifier.weight(1f))
                }
            }
        }
        dragged?.let { id ->
            val size = with(density) { draggedSize.width.toDp() to draggedSize.height.toDp() }
            Box(Modifier.offset { IntOffset((pointerRoot.x - gridOrigin.x - grabOffset.x).roundToInt(), (pointerRoot.y - gridOrigin.y - grabOffset.y).roundToInt()) }
                .size(size.first, size.second).zIndex(10f).alpha(0.92f)) { card(id, Modifier.fillMaxSize(), true) }
        }
    }
}

package com.seolhwa.armyrist.home

import org.json.JSONArray

object HomeToolOrder {
    val defaults = listOf("counting", "checklist", "timeplan", "report", "handicap")
    fun normalize(values: List<String>) = values.filter { it in defaults }.distinct().let { it + defaults.filterNot(it::contains) }
    fun decode(raw: String?): List<String> = runCatching {
        val array = JSONArray(raw ?: return defaults)
        normalize((0 until array.length()).map { array.optString(it) })
    }.getOrDefault(defaults)
    fun encode(values: List<String>) = JSONArray(normalize(values)).toString()
    fun move(values: List<String>, id: String, target: String): List<String> = moveToIndex(values, id, normalize(values).indexOf(target))
    fun moveToIndex(values: List<String>, id: String, index: Int): List<String> {
        val order = normalize(values)
        val from = order.indexOf(id)
        if (from < 0 || index !in order.indices || from == index) return order
        return order.toMutableList().also { it.removeAt(from); it.add(index, id) }
    }
}

package com.seolhwa.armyrist.handicap

import java.time.LocalDateTime
import org.junit.Assert.*
import org.junit.Test

class HandicapTest {
    private val giver = UnitContact("부여제대", "1234")
    private val upper = UnitContact("상급 A", "1111")
    private val lower = UnitContact("하급 B", "2222")
    private val config = HandicapConfig(issuer = giver, upper = listOf(upper) + List(3) { UnitContact() }, lower = listOf(lower) + List(3) { UnitContact() })
    private fun draft(kind: HandicapKind? = HandicapKind.BLACK) = SituationDraft(kind, giver, listOf("불침번"), "2026.10.21 12:30", listOf("위병소"), listOf("화재"), listOf("발견"))
    @Test fun blackGoesToFirstUpper() { assertEquals(upper, HandicapRules.build(config, draft()).recipient) }
    @Test fun whiteGoesToFirstLower() { assertEquals(lower, HandicapRules.build(config, draft(HandicapKind.WHITE)).recipient) }
    @Test fun blackWithoutUpperReturnsToSelectedIssuer() {
        val d = draft().copy(issuer = UnitContact("선택한 부여제대", "4444"))
        assertEquals(d.issuer, HandicapRules.build(config.copy(upper = emptyList()), d).recipient)
    }
    @Test fun blackDoesNotSkipToSecondUpper() {
        val c = config.copy(upper = listOf(UnitContact(), upper, upper, upper))
        assertEquals(giver, HandicapRules.build(c, draft()).recipient)
    }
    @Test fun whiteWithoutFirstLowerReturnsToIssuer() {
        assertEquals(giver, HandicapRules.build(config.copy(lower = listOf(UnitContact(), lower)), draft(HandicapKind.WHITE)).recipient)
    }
    @Test fun blankNameWithPhoneIsNotRegisteredUnit() {
        assertEquals(giver, HandicapRules.build(config.copy(upper = listOf(UnitContact(" ", "9999"))), draft()).recipient)
    }
    @Test fun unitWithoutPhoneStillShowsName() {
        assertEquals(UnitContact("하급"), HandicapRules.build(config.copy(upper = listOf(UnitContact("하급"))), draft()).recipient)
    }
    @Test fun defaultIssuerIsUsedWhenNoExplicitSelection() {
        assertTrue(HandicapRules.build(config, draft().copy(issuer = UnitContact())).missing.isEmpty())
    }
    @Test fun missingIssuerReportedEvenWhenRouteRegistered() {
        assertTrue(HandicapRules.build(config.copy(issuer = UnitContact()), draft().copy(issuer = UnitContact())).missing.contains("상황부여 제대"))
    }
    @Test fun missingFieldsPreventCompleteReport() {
        assertEquals(7, HandicapRules.build(HandicapConfig(), SituationDraft()).missing.size)
    }
    @Test fun completeDraftHasNoMissingFields() { assertTrue(HandicapRules.build(config, draft()).missing.isEmpty()) }
    @Test fun reportFollowsRequestedOrder() {
        assertEquals("2026.10.21 12:30, 위병소에서 불침번 관련 화재 상황발생.\n수행사항: 발견.", HandicapRules.build(config, draft()).sentence)
    }
    @Test fun clickOrderDoesNotAffectReport() {
        val a = draft().copy(who = listOf("불침번", "위병조장"), where = listOf("막사", "위병소"), what = listOf("화재", "응급환자"))
        val b = a.copy(who = a.who.reversed(), where = a.where.reversed(), what = a.what.reversed())
        assertEquals(HandicapRules.build(config, a).sentence, HandicapRules.build(config, b).sentence)
    }
    @Test fun customWordsAppearInSentence() {
        val d = draft().copy(who = listOf("사용자 인원"), whenText = "내일 새벽", where = listOf("사용자 장소"), what = listOf("사용자 상황"))
        assertEquals("내일 새벽, 사용자 장소에서 사용자 인원 관련 사용자 상황 상황발생.\n수행사항: 발견.", HandicapRules.build(config, d).sentence)
    }
    @Test fun currentTimeUsesPassedInstantAndDoesNotTick() {
        assertEquals("2026.10.21 23:59", HandicapRules.currentTime(LocalDateTime.of(2026, 10, 21, 23, 59)))
    }
    @Test fun configRoundTripsAllEightUnitsAndCustomWords() {
        val c = config.copy(upper = List(4) { UnitContact("상급 $it", "$it") }, lower = List(4) { UnitContact("하급 $it", "$it") }, words = WordCategory.entries.associateWith { listOf(SituationWord(it.name, "사용자 ${it.title}")) })
        assertEquals(c, HandicapCodec.decode(HandicapCodec.encode(c)))
    }
    @Test fun deletedDefaultsStayDeleted() {
        val c = config.copy(words = WordCategory.entries.associateWith { emptyList() })
        assertEquals(c, HandicapCodec.decode(HandicapCodec.encode(c)))
    }
    @Test fun malformedConfigUsesDefaults() { assertEquals(HandicapConfig(), HandicapCodec.decode("garbage")) }
    @Test fun absentConfigUsesDefaults() { assertEquals(HandicapConfig(), HandicapCodec.decode(null)) }
    @Test fun missingVocabularyFieldsUseDefaults() { assertEquals(HandicapConfig(), HandicapCodec.decode("{}")) }
    @Test fun duplicateIdsAndEmptyWordsAreRemoved() {
        val c = config.copy(words = mapOf(WordCategory.WHO to listOf(SituationWord("same", "A"), SituationWord("same", "B"), SituationWord("empty", " ")))).normalized()
        assertEquals(listOf(SituationWord("same", "A")), c.words[WordCategory.WHO])
    }
    @Test fun normalizationPadsUnitsAndLimitsInputs() {
        val c = config.copy(upper = emptyList(), issuer = UnitContact("x".repeat(100), "1".repeat(80))).normalized()
        assertEquals(4, c.upper.size); assertEquals(60, c.issuer.name.length); assertEquals(40, c.issuer.phone.length)
    }
    @Test fun draftRoundTripKeepsTimeAndUnsortedSelections() {
        val d = draft().copy(who = listOf("위병조장", "불침번"), whenText = "2026.10.21 12:30")
        assertEquals(d, HandicapCodec.decodeDraft(HandicapCodec.encodeDraft(d)))
    }
    @Test fun malformedDraftIsEmpty() { assertEquals(SituationDraft(), HandicapCodec.decodeDraft("garbage")) }
    @Test fun editorPreservesTrailingSpaceUntilSave() {
        val c = config.copy(issuer = UnitContact("상급 ", "111 "))
        assertEquals(c, HandicapCodec.decode(HandicapCodec.encode(c, normalize = false), normalize = false))
        assertEquals(UnitContact("상급", "111"), HandicapCodec.decode(HandicapCodec.encode(c)).issuer)
    }
    @Test fun routesExplainFallbackAndSelectedType() {
        assertEquals("1차 상급 미등록 → 상황부여 제대", HandicapRules.build(config.copy(upper = emptyList()), draft()).route)
        assertEquals("화이트 ↓ 1차 하급제대", HandicapRules.build(config, draft(HandicapKind.WHITE)).route)
    }

    @Test fun howDefaultsAreDiscoverActReport() {
        assertEquals(listOf("발견", "조치", "보고"), HandicapConfig().words[WordCategory.HOW]!!.map { it.text })
    }
    @Test fun missingHowIsReported() {
        assertEquals(listOf("어떻게"), HandicapRules.build(config, draft().copy(how = emptyList())).missing)
    }
    @Test fun howClickOrderIsCanonical() {
        val a = draft().copy(how = listOf("보고", "발견", "조치"))
        assertTrue(HandicapRules.build(config, a).sentence.endsWith("수행사항: 발견 · 조치 · 보고."))
    }
    @Test fun customHowSurvivesDraftRoundTrip() {
        val d = draft().copy(how = listOf("추가 사용자 조치"))
        assertEquals(d, HandicapCodec.decodeDraft(HandicapCodec.encodeDraft(d)))
    }
    @Test fun placesIncludeNewLocationsAndRenamedBarracks() {
        val places = HandicapConfig().words[WordCategory.WHERE]!!.map { it.text }
        assertTrue(places.containsAll(listOf("통합막사", "생활관", "보일러실")))
        assertFalse("막사" in places)
    }
    @Test fun oldPlaceDefaultsAreMigratedWithoutLosingCustomWords() {
        val raw = """{"words":{"WHERE":[{"id":"WHERE_1","text":"막사"},{"id":"custom","text":"사용자 장소"}]}}"""
        val words = HandicapCodec.decode(raw).words[WordCategory.WHERE]!!.map { it.text }
        assertEquals(listOf("통합막사", "사용자 장소", "생활관", "보일러실"), words)
    }
    @Test fun customBarracksWordIsNotRenamed() {
        val raw = """{"words":{"WHERE":[{"id":"custom","text":"막사"}]}}"""
        assertTrue(HandicapCodec.decode(raw).words[WordCategory.WHERE]!!.any { it.text == "막사" })
    }
    @Test fun migrationDoesNotDuplicateNewLocations() {
        val raw = """{"words":{"WHERE":[{"id":"custom","text":"생활관"},{"id":"WHERE_5","text":"보일러실"}]}}"""
        assertEquals(2, HandicapCodec.decode(raw).words[WordCategory.WHERE]!!.size)
    }
    @Test fun explicitDeletedHowIsPreserved() {
        val c = config.copy(words = config.words + (WordCategory.HOW to emptyList()))
        assertTrue(HandicapCodec.decode(HandicapCodec.encode(c)).words[WordCategory.HOW]!!.isEmpty())
    }
    @Test fun oldDraftDoesNotInventHowSelection() {
        assertTrue(HandicapCodec.decodeDraft("""{"kind":"BLACK","what":["화재"]}""").how.isEmpty())
    }
}

